	-- true if the uploaded images show upside down on the cards (Config.HairAssets.flipV overrides)
	flipV = false,
	-- greyscale albedo + straight alpha, tinted per boxer on the client. size = the uploaded image's size;
	-- tile = tileable (one flat colour, no root-to-tip dye); gain (optional) = albedo multiplier
